local function makeTheme(d)
	local function grey(v)
		v *= d[5]
		return Color3.fromRGB(math.min(v * d[2], 255), math.min(v * d[3], 255), math.min(v * d[4], 255))
	end
	-- text only takes half of the tint, so it stays easy to read
	local function ink(v)
		local function half(t) return math.min(v * (1 + t) / 2, 255) end
		return Color3.fromRGB(half(d[2]), half(d[3]), half(d[4]))
	end
	return {
		["Window Background"] = grey(30), ["Section Background"] = grey(26), ["Inline"] = grey(64), ["Element"] = grey(42), ["Border"] = grey(58),
		["Outline"] = grey(11), ["Dark Liner"] = grey(22), ["Highlight"] = grey(80), ["Element Hover"] = grey(56), ["Shadow"] = Color3.new(0, 0, 0),
		["Text"] = ink(200), ["Bright Text"] = Color3.new(1, 1, 1), ["Dim Text"] = ink(138), ["Risky"] = Color3.fromRGB(235, 80, 80),
		["Accent"] = Color3.fromRGB(d[6], d[7], d[8]),
	}
end
Library.ThemeOrder = { "Default" }
for _, d in THEME_LIST do
	Library.Themes[d[1]] = makeTheme(d)
	table.insert(Library.ThemeOrder, d[1])
end
do
	local rgb = Color3.fromRGB
	Library.Themes["Light"] = {
		["Window Background"] = rgb(232, 233, 237), ["Section Background"] = rgb(242, 243, 246), ["Inline"] = rgb(186, 189, 198), ["Element"] = rgb(220, 222, 228), ["Border"] = rgb(198, 201, 209),
		["Outline"] = rgb(150, 154, 165), ["Dark Liner"] = rgb(226, 228, 233), ["Highlight"] = rgb(170, 174, 185), ["Element Hover"] = rgb(206, 209, 217), ["Shadow"] = rgb(90, 92, 100),
		["Text"] = rgb(48, 50, 58), ["Bright Text"] = rgb(14, 15, 20), ["Dim Text"] = rgb(112, 116, 128), ["Risky"] = rgb(205, 50, 50), ["Accent"] = rgb(207, 31, 69),
	}
	table.insert(Library.ThemeOrder, "Light")
end
Library.Theme = table.clone(Library.Themes.Default)

local function wrapInst(inst) return { Instance = inst } end
Library.Wrap = wrapInst

function Library:AddToTheme(item, props)
	local inst = typeof(item) == "Instance" and item or item.Instance
	if typeof(inst) ~= "Instance" then return end
	local map = self.ThemeMap[inst]
	if not map then map = { Instance = inst, Properties = {} } self.ThemeMap[inst] = map self.ThemeItems[#self.ThemeItems + 1] = map end
	for prop, key in props do
		map.Properties[prop] = key
		local v = type(key) == "string" and self.Theme[key] or key
		if v ~= nil then pcall(function() inst[prop] = v end) end
	end
end
-- a colour that changes at runtime (selected / active states) must stay bound to its theme key, or the next theme change would reset it
function Library.themed(inst, prop, keyOrColor)
	if type(keyOrColor) == "string" then Library:AddToTheme(inst, { [prop] = keyOrColor })
	else
		local map = Library.ThemeMap[inst]
		if map then map.Properties[prop] = nil end
		inst[prop] = keyOrColor
	end
end
function Library:ChangeItemTheme(item, props)
	local inst = typeof(item) == "Instance" and item or item.Instance
	local map = self.ThemeMap[inst]
	if not map then self:AddToTheme(inst, {}) map = self.ThemeMap[inst] end
	for prop in map.Properties do map.Properties[prop] = nil end
	for prop, key in props do map.Properties[prop] = key end
end
function Library:ChangeTheme(key, color)
	self.Theme[key] = color
	for i = #self.ThemeItems, 1, -1 do
		local m = self.ThemeItems[i]
		if not m.Instance.Parent and not m.Instance:IsDescendantOf(game) then table.remove(self.ThemeItems, i)
		else for prop, k in m.Properties do if k == key then pcall(function() m.Instance[prop] = color end) end end end
	end
end
Build.Theme = function(inst, map) Library:AddToTheme(inst, map) end

-- ---- helpers ----
function Library:NextFlag() self.FlagCount += 1 return "Flag_" .. self.FlagCount end
function Library:Connect(signal, fn, name)
	local c = signal:Connect(fn)
	self.Connections[#self.Connections + 1] = c
	return c
end
function Library:Disconnect(c) if c then pcall(function() c:Disconnect() end) end end
function Library:SafeCall(fn, ...)
	if type(fn) ~= "function" then return end
	local ok, err = pcall(fn, ...)
	if not ok then
		warn("[Library] callback error: " .. tostring(err))
		if self.Notification then pcall(self.Notification, self, "Callback error: " .. tostring(err), 4, Color3.fromRGB(235, 90, 90)) end
	end
end
function Library:Round(n, step) step = tonumber(step) or 1 if step <= 0 then return n end return math.floor(n / step + 0.5) * step end
function Library:IsMouseOverFrame(frame)
	local inset = game:GetService("GuiService"):GetGuiInset()
	local p = UserInputService:GetMouseLocation() - inset   -- AbsolutePosition and InputObject.Position are both without the top bar inset
	local a, s = frame.AbsolutePosition, frame.AbsoluteSize
	return p.X >= a.X and p.X <= a.X + s.X and p.Y >= a.Y and p.Y <= a.Y + s.Y
end
function Library:TweenTo(inst, props, time)
	local t = TweenService:Create(inst, TweenInfo.new(Library.Animations == false and 0 or (time or self.Tween.Time), self.Tween.Style, self.Tween.Direction), props)
	t:Play()
	return t
end
local function field(Data, ...) for _, k in { ... } do local v = Data[k] if v ~= nil then return v end end end
Library.field = field

-- ---- assets: font + icons ----
do
	local getasset = getcustomasset or getsynasset
	local b64 = (crypt and (crypt.base64decode or (crypt.base64 and crypt.base64.decode))) or base64decode or (base64 and base64.decode)
	pcall(function()
		for _, f in { Library.Folders.Directory, Library.Folders.Assets, Library.Folders.Icons } do if makefolder and not (isfolder and isfolder(f)) then makefolder(f) end end
	end)
	if type(writefile) == "function" and getasset and b64 then
		for name, ic in Build.IconPng do
			pcall(function()
				local path = Library.Folders.Icons .. "/" .. name .. ".png"
				-- tab and fx images are rewritten every load so a changed set is never shadowed by a cached file
				local pre = name:sub(1, 3)
				if pre == "tab" or pre == "fx_" or not (isfile and isfile(path)) then writefile(path, b64(ic.b64)) end
				Build.IconAsset[name] = getasset(path)
			end)
		end
	end
	-- Roblox's built-in Ubuntu family (no getcustomasset / manifest write is involved): Medium for text, Bold for the window name.
	-- An Env.FontFace replaces both.
	local function ubuntu(weight, fallback)
		local ok, f = pcall(function() return Font.new("rbxasset://fonts/families/Ubuntu.json", weight) end)
		return ok and f or Font.fromEnum(fallback)
	end
	local face, bold = Library.Env.FontFace, nil
	if typeof(face) ~= "Font" then
		face = ubuntu(Enum.FontWeight.Medium, Enum.Font.Ubuntu)
		bold = ubuntu(Enum.FontWeight.Bold, Enum.Font.Ubuntu)
	else
		bold = face
	end
	Library.Font, Library.FontBold, Library.FontLight = face, bold, face
	Build.Font, Build.FontBold = face, bold
end

-- ---- holder ----
do
	local gui = Instance.new("ScreenGui")
	gui.Name = "\0"
	gui.ResetOnSpawn = false
	gui.IgnoreGuiInset = true
	gui.DisplayOrder = 100000
	gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
	pcall(function() gui.Parent = (gethui and gethui()) or game:GetService("CoreGui") end)
	if not gui.Parent then gui.Parent = Players.LocalPlayer:WaitForChild("PlayerGui") end
	Library.Holder = wrapInst(gui)
	function Library.Holder:Clean() pcall(function() gui:Destroy() end) end
end

function Library:Unload()
	if not self.Alive then return end
	self.Alive = false
	for _, c in self.Connections do pcall(function() c:Disconnect() end) end
	for _, t in self.Threads do pcall(task.cancel, t) end
	if self.OnUnload then for _, fn in self.OnUnload do pcall(fn) end end
	self.Holder:Clean()
	if getgenv then getgenv().Library = nil end
end

-- ---- dragging ----
local function makeDraggable(handle, target)
	local dragging, start, startPos
	Library:Connect(handle.InputBegan, function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
			dragging, start, startPos = true, i.Position, target.Position
		end
	end)
	Library:Connect(UserInputService.InputChanged, function(i)
		if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
			local d = i.Position - start
			target.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + d.X, startPos.Y.Scale, startPos.Y.Offset + d.Y)
		end
	end)
	Library:Connect(UserInputService.InputEnded, function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then dragging = false end
	end)
end
Library.MakeDraggable = makeDraggable

local function listLayout(parent, pad, dir)
	local l = Instance.new("UIListLayout")
	l.Padding = UDim.new(0, pad or 0)
	l.SortOrder = Enum.SortOrder.LayoutOrder
	if dir then l.FillDirection = dir end
	l.Parent = parent
	return l
end
Library.listLayout = listLayout

local function click(inst, fn)
	local b = Instance.new("TextButton")
	b.BackgroundTransparency = 1
	b.Text = ""
	b.AutoButtonColor = false
	b.Size = UDim2.fromScale(1, 1)
	b.ZIndex = inst.ZIndex + 1
	b.Parent = inst
	if fn then Library:Connect(b.MouseButton1Click, fn) end
	return b
end
Library.click = click

-- ---- touch devices ----
-- Library.IsMobile: a phone or tablet (touch, no physical keyboard). Env.Mobile / getgenv().AllisonMobile = true forces it, false turns it off.
do
	local forced = Library.Env.Mobile
	if forced == nil and getgenv then forced = getgenv().AllisonMobile end
	if forced ~= nil then
		Library.IsMobile = forced == true
	else
		Library.IsMobile = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
	end
end
function Library:FitScaleFor(w, h)
	local cam = workspace.CurrentCamera
	local v = cam and cam.ViewportSize or Vector2.new(1280, 720)
	return math.clamp(math.min(v.X * 0.96 / math.max(w, 1), v.Y * 0.92 / math.max(h, 1)), 0.35, 1)
end
-- the circle that opens / closes every window instead of the keybind; drag it to move it (a tap that moves less than 8 px toggles)
function Library:MobileButton(title)
	if self.MobileToggle or not self.Alive then return self.MobileToggle end
	local SIZE = 52
	local cam = workspace.CurrentCamera
	local function viewport() return cam and cam.ViewportSize or Vector2.new(1280, 720) end
	local btn = Instance.new("TextButton")
	btn.Name = "\0"
	btn.AutoButtonColor, btn.Text, btn.BorderSizePixel = false, "", 0
	btn.Size = UDim2.fromOffset(SIZE, SIZE)
	btn.Position = UDim2.new(1, -SIZE - 14, 0.5, -SIZE / 2)
	btn.ZIndex = 9000
	btn.BackgroundColor3 = self.Theme["Window Background"]
	Library.themed(btn, "BackgroundColor3", "Window Background")
	Instance.new("UICorner", btn).CornerRadius = UDim.new(0.5, 0)
	local stroke = Instance.new("UIStroke", btn)
	stroke.Thickness, stroke.ApplyStrokeMode, stroke.Color = 2, Enum.ApplyStrokeMode.Border, self.Theme.Accent
	Library.themed(stroke, "Color", "Accent")
	local scale = Instance.new("UIScale", btn)
	local glyph = Instance.new("TextLabel")
	glyph.Name = "\0"
	glyph.BackgroundTransparency, glyph.Size, glyph.ZIndex = 1, UDim2.fromScale(1, 1), 9001
	glyph.FontFace, glyph.TextSize = self.FontBold, 24
	glyph.Text = string.upper(tostring(title or "A"):sub(1, 1))
	glyph.TextColor3 = self.Theme.Accent
	Library.themed(glyph, "TextColor3", "Accent")
	glyph.Parent = btn
	btn.Parent = self.Holder.Instance
	local function anyOpen() for _, w in self.Windows do if w.IsOpen then return true end end return false end
	local function refresh()
		local open = anyOpen()
		Library.fx.tween(btn, { BackgroundTransparency = open and 0 or 0.25 }, 0.15)
		Library.fx.tween(glyph, { TextTransparency = open and 0 or 0.2 }, 0.15)
	end
	local drag, moved, startAt, startPos
	self:Connect(btn.InputBegan, function(i)
		if i.UserInputType ~= Enum.UserInputType.Touch and i.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
		drag, moved = i, false
		startAt, startPos = Vector2.new(i.Position.X, i.Position.Y), Vector2.new(btn.AbsolutePosition.X, btn.AbsolutePosition.Y)
		Library.fx.tween(scale, { Scale = 0.92 }, 0.08)
	end)
	self:Connect(UserInputService.InputChanged, function(i)
		if not drag or not (i == drag or i.UserInputType == Enum.UserInputType.MouseMovement) then return end
		local d = Vector2.new(i.Position.X, i.Position.Y) - startAt
		if not moved and d.Magnitude < 8 then return end
		moved = true
		local v = viewport()
		-- the holder ignores the top bar inset, so AbsolutePosition and the input position share one origin
		btn.Position = UDim2.fromOffset(math.clamp(startPos.X + d.X, 4, v.X - SIZE - 4), math.clamp(startPos.Y + d.Y, 4, v.Y - SIZE - 4))
	end)
	self:Connect(UserInputService.InputEnded, function(i)
		if not drag or not (i == drag or i.UserInputType == Enum.UserInputType.MouseButton1) then return end
		local wasTap = not moved
		drag = nil
		Library.fx.tween(scale, { Scale = 1 }, 0.12)
		if wasTap then
			local open = not anyOpen()
			for _, w in self.Windows do w:SetOpen(open) end
			refresh()
		end
	end)
	self.MobileToggle = { Button = btn, Refresh = refresh }
	refresh()
	return self.MobileToggle
end

-- ---- Window ----
-- Aurora Hex: a double-edged flat window, the name centred in the top edge ("aurora hex" = the first word in the accent colour,
-- the rest white), a search field top right, equal-width tabs across the top, the pages below. Dragged by the title row, resized
-- by the grip in the bottom-right corner. Every call makes another window (a second one opens offset from the first).
function Library:Window(Data)
	Data = Data or {}
	local name = field(Data, "Name", "name") or "aurora hex"
	local size = field(Data, "Size", "size")
	local fx = Library.fx
	local W = Build.Window(self.Holder.Instance)
	local root = W.Root
	root.Name = "\0"
	root.AnchorPoint = Vector2.new(0.5, 0.5)
	local nth = #self.Windows
	root.Position = UDim2.new(0.5, nth * 28, 0.5, nth * 28)
	if typeof(size) == "UDim2" then root.Size = size end
	-- the two-tone title, centred
	local first, rest = tostring(name):match("^(%S+)%s*(.*)$")
	W.title.Text, W.title2.Text = first or tostring(name), rest or ""
	for _, t in { W.title, W.title2 } do
		t.FontFace = Library.FontBold
		t.AutomaticSize = Enum.AutomaticSize.X
		t.Size = UDim2.new(0, 0, 1, 0)
		t.TextXAlignment = Enum.TextXAlignment.Left
	end
	W.title.LayoutOrder, W.title2.LayoutOrder = 1, 2
	local tl = listLayout(W.titleRow, 4, Enum.FillDirection.Horizontal)
	tl.HorizontalAlignment, tl.VerticalAlignment = Enum.HorizontalAlignment.Center, Enum.VerticalAlignment.Center
	W.title2.Visible = W.title2.Text ~= ""
	W.titleRow.AnchorPoint, W.titleRow.Position = Vector2.new(0.5, 0), UDim2.new(0.5, 0, 0, -7)
	W.titleRow.AutomaticSize = Enum.AutomaticSize.X
	W.titleRow.Size = UDim2.new(0, 0, 0, 16)
	local tpad = Instance.new("UIPadding", W.titleRow)
	tpad.PaddingLeft, tpad.PaddingRight = UDim.new(0, 5), UDim.new(0, 5)
	W.titleRow.ZIndex = 3
	-- tabs and pages
	listLayout(W.tabs, 6, Enum.FillDirection.Horizontal)
	local window = setmetatable({ Items = {}, Pages = {}, IsOpen = true, Library = self, _W = W, FadeWith = {} }, self)
	window.Items["Outline"] = wrapInst(root)
	window.Items["Title"] = wrapInst(W.titleRow)
	window.Items["Pages"] = wrapInst(W.tabs)
	window.Items["Content"] = wrapInst(W.pages)
	window.Items["Search"] = wrapInst(W.search)
	makeDraggable(W.titleRow, root)
	makeDraggable(W.dragBar, root)
	window.SearchItems, window.SectionList = {}, {}
	-- the search field: a real TextBox over the design's text
	W.searchText.Visible = false
	local sbox = Instance.new("TextBox")
	sbox.BackgroundTransparency, sbox.BorderSizePixel = 1, 0
	sbox.Size, sbox.Position = UDim2.new(1, -20, 1, 0), UDim2.new(0, 18, 0, 0)
	sbox.FontFace, sbox.TextSize, sbox.TextXAlignment = Library.Font, 12, Enum.TextXAlignment.Left
	sbox.TextColor3, sbox.PlaceholderColor3 = Library.Theme.Text, Library.Theme["Dim Text"]
	sbox.PlaceholderText, sbox.Text, sbox.ClearTextOnFocus = "search", "", false
	sbox.Parent = W.search
	window.Items["SearchBox"] = wrapInst(sbox)
	Library:Connect(sbox:GetPropertyChangedSignal("Text"), function() if Library.SearchWindow then Library.SearchWindow(window, sbox.Text) end end)
	local searchStroke = W.search:FindFirstChildOfClass("UIStroke")
	Library:Connect(sbox.Focused, function() if searchStroke then Library.themed(searchStroke, "Color", "Accent") end end)
	Library:Connect(sbox.FocusLost, function() if searchStroke then Library.themed(searchStroke, "Color", "Outline") end end)
	-- resize from the grip (sizes are offsets; the window's centre anchor moves by half the growth so the top-left corner stays put)
	do
		local dragging, start, startSize, startPos = false, nil, nil, nil
		local btn = click(W.grip)
		Library:Connect(btn.InputBegan, function(i)
			if i.UserInputType ~= Enum.UserInputType.MouseButton1 and i.UserInputType ~= Enum.UserInputType.Touch then return end
			dragging, start, startSize, startPos = true, Vector2.new(i.Position.X, i.Position.Y), root.Size, root.Position
		end)
		Library:Connect(UserInputService.InputChanged, function(i)
			if not (dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch)) then return end
			local d = Vector2.new(i.Position.X, i.Position.Y) - start
			local sc = root:FindFirstChildOfClass("UIScale")
			local k = (sc and sc.Scale > 0) and sc.Scale or 1
			local w = math.max(startSize.X.Offset + d.X / k, 480)
			local h = math.max(startSize.Y.Offset + d.Y / k, 360)
			root.Size = UDim2.new(startSize.X.Scale, w, startSize.Y.Scale, h)
			root.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + (w - startSize.X.Offset) * k / 2, startPos.Y.Scale, startPos.Y.Offset + (h - startSize.Y.Offset) * k / 2)
		end)
		Library:Connect(UserInputService.InputEnded, function(i)
			if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then dragging = false end
		end)
	end
	-- open / close: the window fades and pops in, and fades and shrinks away. It animates the UIScale already on the window (a script's DPI setting puts
	-- one there) around its current value, or a temporary one that is removed afterwards. The fade is a CanvasGroup over the whole screen that holds the
	-- window (and window.FadeWith: frames that belong to it) only while it runs, because text in a CanvasGroup is softer.
	local anim = { token = 0 }
	local function fadeGroup()
		if not anim.group then
			local g = Instance.new("CanvasGroup")
			g.Name = "\0"
			g.BackgroundTransparency, g.BorderSizePixel = 1, 0
			g.Size = UDim2.fromScale(1, 1)
			g.ZIndex = root.ZIndex
			g.Parent = root.Parent
			anim.group, anim.home = g, root.Parent
		end
		anim.group.Visible = true
		root.Parent = anim.group
		for _, f in window.FadeWith do if f.Parent then f.Parent = anim.group end end
		return anim.group
	end
	local function fadeDone()
		if not anim.group then return end
		root.Parent = anim.home
		for _, f in window.FadeWith do if f.Parent then f.Parent = anim.home end end
		anim.group.Visible = false
	end
	function window:SetOpen(bool)
		self.IsOpen = bool
		anim.token += 1
		local my = anim.token
		if Library.UpdateBlur then Library.UpdateBlur() end
		if self.OnOpen then self.OnOpen(bool) end
		if Library.MobileToggle then Library.MobileToggle.Refresh() end
		if not Library.Animations then root.Visible = bool return end
		local sc = anim.temp or root:FindFirstChildOfClass("UIScale")
		if not anim.base then
			if not sc then
				sc = Instance.new("UIScale")
				sc.Name = "\0Open"
				sc.Parent = root
				anim.temp = sc
			end
			anim.base = sc.Scale
		end
		local base = anim.base
		local function finish()
			if anim.token ~= my then return end
			sc.Scale = base
			anim.base = nil
			if anim.temp then anim.temp:Destroy() anim.temp = nil end
			fadeDone()
		end
		local group = fadeGroup()
		if bool then
			if not root.Visible then
				sc.Scale = base * 0.94
				group.GroupTransparency = 1
			end
			root.Visible = true
			fx.tween(group, { GroupTransparency = 0 }, 0.2, Enum.EasingStyle.Quad)
			fx.tween(sc, { Scale = base }, 0.22, Enum.EasingStyle.Quint).Completed:Connect(finish)
		else
			fx.tween(group, { GroupTransparency = 1 }, 0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
			fx.tween(sc, { Scale = base * 0.94 }, 0.14, Enum.EasingStyle.Quad, Enum.EasingDirection.In).Completed:Connect(function()
				if anim.token == my then root.Visible = false end
				finish()
			end)
		end
	end
	Library:Connect(UserInputService.InputBegan, function(i, gpe)
		if gpe and UserInputService:GetFocusedTextBox() then return end
		if tostring(i.KeyCode) == Library.MenuKeybind or tostring(i.UserInputType) == Library.MenuKeybind then window:SetOpen(not window.IsOpen) end
	end)
	-- phones and tablets: the window is scaled to fit the screen (window.UserScale, e.g. a script's DPI setting, multiplies it) and the
	-- circle button opens / closes the menu instead of the keybind
	window.UserScale = 1
	function window:Refit()
		if anim.base then return end   -- an open / close animation owns the scale right now
		local sc = root:FindFirstChildOfClass("UIScale")
		if not Library.IsMobile then
			if sc and sc.Name == "\0Fit" then sc.Scale = self.UserScale end
			return
		end
		if not sc then
			sc = Instance.new("UIScale")
			sc.Name = "\0Fit"
			sc.Parent = root
		end
		Library.FitScale = Library:FitScaleFor(root.Size.X.Offset, root.Size.Y.Offset)
		sc.Scale = Library.FitScale * self.UserScale
	end
	if Library.IsMobile then
		-- not on every Size change: the resize grip would fight the fit. A script that sets the size after creating the window calls window:Refit().
		task.delay(0.5, function() if Library.Alive then window:Refit() end end)
		local cam = workspace.CurrentCamera
		if cam then Library:Connect(cam:GetPropertyChangedSignal("ViewportSize"), function() window:Refit() end) end
		root.Position = UDim2.fromScale(0.5, 0.5)
		window:Refit()
		Library:MobileButton(name)
	end
	self.Windows[#self.Windows + 1] = window
	self.Window_ = self.Window_ or window
	return window
end

-- popups (dropdown lists, colour pickers, key modes) live INSIDE the window frame: coordinates relative to it need no inset maths and
-- they move with the window
-- elements register themselves for the window search (name -> frame)
function Library.regSearch(section, root, name)
	if not (section and section.Window and root) then return end
	table.insert(section.Window.SearchItems, { root = root, name = tostring(name or ""), section = section })
end
function Library.popupRoot(section) return section.Window._W.Root end
function Library.popupAt(popup, root, anchor, dy)
	local ra, a, s = root.AbsolutePosition, anchor.AbsolutePosition, anchor.AbsoluteSize
	popup.Position = UDim2.new(0, a.X - ra.X, 0, a.Y - ra.Y + s.Y + (dy or 4))
end

-- ---- Page (a tab across the top + a set of columns) ----
function Library:Page(Data)
	Data = Data or {}
	local window = self
	local W = window._W
	local fx = Library.fx
	local name = field(Data, "Name", "name") or "Page"
	local columns = field(Data, "Columns", "columns") or 2
	local T = Build.Tab(W.tabs)
	T.Root.LayoutOrder = #window.Pages + 1
	T.label.Text = tostring(name)
	T.label.Position, T.label.Size = UDim2.new(), UDim2.new(1, 0, 1, -3)
	T.label.TextYAlignment = Enum.TextYAlignment.Center
	-- the icon (Font Awesome Free, assets/tab_icons.json) left of the name: Data.Icon, or the page name ("Anti-Aim" -> antiaim). The pair is centred.
	local iconName = tostring(field(Data, "Icon", "icon") or string.lower((tostring(name):gsub("[^%w]", ""))))
	local iconId = Build.IconAsset["tab_" .. iconName]
	local icon
	if iconId and iconId ~= "" then
		icon = Instance.new("ImageLabel")
		icon.Name = "\0"
		icon.BackgroundTransparency, icon.BorderSizePixel = 1, 0
		icon.Image = iconId
		icon.AnchorPoint = Vector2.new(0, 0.5)
		icon.Size = UDim2.fromOffset(14, 14)
		icon.ImageColor3 = Library.Theme["Dim Text"]
		icon.Parent = T.Root
		local function place()
			-- icon (14 px) + 7 px gap + the text, the whole pair centred in the tab
			local b = T.label.TextBounds.X
			local left = -(21 + b) / 2
			icon.Position = UDim2.new(0.5, left, 0.5, -1)
			T.label.TextXAlignment = Enum.TextXAlignment.Left
			T.label.AnchorPoint = Vector2.new(0, 0)
			T.label.Position, T.label.Size = UDim2.new(0.5, left + 21, 0, 0), UDim2.new(0, b + 6, 1, -3)
		end
		place()
		T.label:GetPropertyChangedSignal("TextBounds"):Connect(place)
	end
	local holder = Instance.new("Frame")
	holder.Name = "\0"
	holder.BackgroundTransparency = 1
	holder.Size = UDim2.fromScale(1, 1)
	holder.Visible = false
	holder.Parent = W.pages
	listLayout(holder, 0, Enum.FillDirection.Horizontal)
	local page = setmetatable({ Items = {}, ColumnsData = {}, Window = window, Library = Library, Name = name, Columns = columns }, Library)
	for i = 1, columns do
		local col = Instance.new("ScrollingFrame")
		col.Name = "\0"
		col.BackgroundTransparency = 1
		col.BorderSizePixel = 0
		col.ScrollBarThickness = 2
		col.ScrollBarImageColor3 = Library.Theme.Accent
		col.CanvasSize = UDim2.new()
		col.AutomaticCanvasSize = Enum.AutomaticSize.Y
		col.Size = UDim2.new(1 / columns, 0, 1, 0)
		col.Parent = holder
		local cpad = Instance.new("UIPadding")
		cpad.PaddingLeft = UDim.new(0, i == 1 and 0 or 5)
		cpad.PaddingRight = UDim.new(0, i == columns and 4 or 5)
		cpad.PaddingBottom = UDim.new(0, 6)
		cpad.Parent = col
		listLayout(col, 8)
		page.ColumnsData[i] = wrapInst(col)
	end
	page.Items["Inactive"] = wrapInst(T.Root)
	page.Items["Page"] = wrapInst(holder)
	-- the tabs share the row's width equally
	window.Pages[#window.Pages + 1] = page
	local n = #window.Pages
	for _, p in window.Pages do
		p.Items["Inactive"].Instance.Size = UDim2.new(1 / n, -6 * (n - 1) / n, 1, 0)
	end
	local active = false
	page.Holder = holder
	function page:Turn(bool, keepPage)
		local was = active
		active = bool
		if not keepPage then holder.Visible = bool end
		local key = bool and "Bright Text" or "Dim Text"
		Library:ChangeItemTheme(T.label, { TextColor3 = key })
		fx.tween(T.label, { TextColor3 = Library.Theme[key] }, 0.18)
		if icon then
			Library:ChangeItemTheme(icon, { ImageColor3 = bool and "Accent" or key })
			fx.tween(icon, { ImageColor3 = bool and Library.Theme.Accent or Library.Theme[key] }, 0.18)
		end
		Library:ChangeItemTheme(T.bar, { BackgroundColor3 = bool and "Accent" or "Border" })
		fx.tween(T.bar, { BackgroundColor3 = bool and Library.Theme.Accent or Library.Theme.Border }, 0.18)
		if bool and not was and not keepPage then
			holder.Position = UDim2.new(0, 0, 0, 8)
			fx.tween(holder, { Position = UDim2.new() }, 0.22)
		end
	end
	-- changing tab: the tab lights up at once, the old page fades out under a cover in the panel's colour, the new one slides and fades in
	local btn = click(T.Root, function()
		if active then return end
		if not Library.Animations then
			for _, p in window.Pages do p:Turn(p == page) end
			return
		end
		for _, p in window.Pages do p:Turn(p == page, true) end
		local cover = window.PageCover
		if not cover then
			cover = Instance.new("Frame")
			cover.Name = "\0"
			cover.BorderSizePixel = 0
			cover.BackgroundColor3 = Library.Theme["Section Background"]
			Library:AddToTheme(cover, { BackgroundColor3 = "Section Background" })
			cover.BackgroundTransparency = 1
			cover.Size = UDim2.new(1, 0, 1, 0)
			cover.ZIndex = 50
			cover.Parent = W.pages
			window.PageCover = cover
		end
		window.PageToken = (window.PageToken or 0) + 1
		local my = window.PageToken
		fx.tween(cover, { BackgroundTransparency = 0 }, 0.09, Enum.EasingStyle.Quad).Completed:Connect(function()
			if window.PageToken ~= my then return end
			for _, p in window.Pages do p.Holder.Visible = p == page end
			holder.Position = UDim2.new(0, 0, 0, 8)
			fx.tween(holder, { Position = UDim2.new() }, 0.22)
			fx.tween(cover, { BackgroundTransparency = 1 }, 0.18, Enum.EasingStyle.Quad)
		end)
	end)
	fx.hover(btn, function() if not active then fx.tween(T.label, { TextColor3 = Library.Theme.Text }, 0.12) if icon then fx.tween(icon, { ImageColor3 = Library.Theme.Text }, 0.12) end end end,
		function() if not active then fx.tween(T.label, { TextColor3 = Library.Theme["Dim Text"] }, 0.18) if icon then fx.tween(icon, { ImageColor3 = Library.Theme["Dim Text"] }, 0.18) end end end)
	page:Turn(n == 1)
	return page
end

-- ---- Section (a groupbox: the title sits in the top edge) ----
function Library:Section(Data)
	Data = Data or {}
	local page = self
	local name = field(Data, "Name", "name") or "Section"
	local side = field(Data, "Side", "side") or 1
	local colWrap = page.ColumnsData[math.clamp(side, 1, page.Columns)]
	local S = Build.Section(colWrap.Instance)
	S.Root.AutomaticSize = Enum.AutomaticSize.Y
	S.Root.Size = UDim2.new(1, 0, 0, 0)
	-- the mask strip (window colour) grows with the title and hides the card's edge behind it
	S.title.Text = tostring(name)
	S.title.AutomaticSize = Enum.AutomaticSize.X
	S.title.Position, S.title.Size = UDim2.new(0, 3, 0, 0), UDim2.new(0, 0, 1, 0)
	S.titleMask.AutomaticSize = Enum.AutomaticSize.X
	S.titleMask.Size = UDim2.new(0, 0, 0, 12)
	Instance.new("UIPadding", S.titleMask).PaddingRight = UDim.new(0, 3)
	S.titleMask.ZIndex, S.title.ZIndex = 3, 4
	S.titleMask.Visible = S.title.Text ~= ""
	S.card.AutomaticSize = Enum.AutomaticSize.Y
	S.card.Size = UDim2.new(1, 0, 0, 0)
	local pad = Instance.new("UIPadding")
	pad.PaddingTop, pad.PaddingBottom, pad.PaddingLeft, pad.PaddingRight = UDim.new(0, 12), UDim.new(0, 7), UDim.new(0, 6), UDim.new(0, 6)
	pad.Parent = S.card
	S.content.AutomaticSize = Enum.AutomaticSize.Y
	S.content.Size = UDim2.new(1, 0, 0, 0)
	S.content.Position = UDim2.new()
	listLayout(S.content, 2)
	local section = setmetatable({ Items = {}, Page = page, Window = page.Window, Library = Library, Name = name }, Library)
	table.insert(page.Window.SectionList, { section = section, root = S.Root, page = page, name = tostring(name) })
	section.Items["Section"] = wrapInst(S.Root)
	section.Items["Content"] = wrapInst(S.content)
	section._S = S
	return section
end


-- ===== runtime/fx.lua =====
-- runtime part 1b (uilibAurora): fx - drop shadows, glows, bevels, hover / press / ripple and the shared tween. Uses Library, Build from core.
-- The shadow / glow images (fx_shadow, fx_glow, fx_ripple; tools/fxassets.mjs) are 128 px 9-slice PNGs whose box (24..104, radius 10)
-- is punched out: they are parented INSIDE the element (a child always draws above its parent with ZIndexBehavior.Sibling) and only
-- the halo outside the element shows. Without getcustomasset the images are "" and the effects quietly do nothing.
local fx = {}
Library.fx = fx
Library.Animations = true
-- Aurora Hex is flat (imgui): no bevels, glows or ripples unless an element forces one (opt.force / fx.bevel(..., true)). Drop shadows
-- ARE drawn, square like the boxes: two layers of fx_shadowsq (a 3 px dropped, square-holed 9-slice), a wide soft ambient one and a
-- tight key one just under the box, so floating panels sit above the window. Library.Shadows = false turns them off.
local FLAT = true
local SLICE = Rect.new(34, 34, 94, 94)
local SLICE_SQ = Rect.new(26, 26, 102, 102)
Library.Shadows = true

-- every animation goes through here; Library.Animations = false makes them instant
function fx.tween(inst, props, t, style, dir)
	local tw = TweenService:Create(inst, TweenInfo.new(Library.Animations and (t or 0.2) or 0, style or Enum.EasingStyle.Quint, dir or Enum.EasingDirection.Out), props)
	tw:Play()
	return tw
end

-- a UIPadding on the element moves and shrinks its children, so the halo is pushed back out by the same amount
local function padOf(inst)
	local p = inst:FindFirstChildOfClass("UIPadding")
	if not p then return 0, 0, 0, 0 end
	return p.PaddingLeft.Offset, p.PaddingRight.Offset, p.PaddingTop.Offset, p.PaddingBottom.Offset
end

-- fx.shadow(inst, { radius, transparency, color (theme key or Color3), glow }) -> ImageLabel
-- radius = the element's corner radius, so the punched-out hole matches its corners
local function layer(inst, spread, transparency, l, r, t, b, name)
	local img = Instance.new("ImageLabel")
	img.Name = name
	img.BackgroundTransparency, img.BorderSizePixel = 1, 0
	img.Image = Build.IconAsset.fx_shadowsq or ""
	img.ScaleType = Enum.ScaleType.Slice
	img.SliceCenter = SLICE_SQ
	img.SliceScale = spread / 24
	img.Position = UDim2.new(0, -spread - l, 0, -spread - t)
	img.Size = UDim2.new(1, spread * 2 + l + r, 1, spread * 2 + t + b)
	img.ImageTransparency = transparency
	img.ZIndex = 0
	img.Parent = inst
	Library:AddToTheme(img, { ImageColor3 = "Shadow" })
	return img
end
-- the layered square shadow: the ambient layer is returned (callers tween its ImageTransparency); the key layer follows it
local function squareShadow(inst, opt)
	local l, r, t, b = padOf(inst)
	local size = math.clamp((opt.radius or 10) / 12, 0.3, 1)   -- the old corner radius doubles as "how far it floats"
	local amb = layer(inst, 24 * size, 1, l, r, t, b, "ShadowAmbient")
	-- the key layer (dark, short, right under the box) only for things that float: panels, popups, windows (radius >= 10).
	-- Buttons and swatches (there are hundreds) keep the one soft layer.
	local key = (opt.radius or 10) >= 10 and layer(inst, math.max(6 * size, 3), 1, l, r, t, b, "ShadowKey") or nil
	local function follow()
		local a = amb.ImageTransparency
		-- the ambient layer is soft and wide (it carries the given transparency); the key layer is darker and short
		if key then key.ImageTransparency = 1 - (1 - a) * 0.85 end
	end
	if key then amb:GetPropertyChangedSignal("ImageTransparency"):Connect(follow) end
	amb.ImageTransparency = math.clamp((opt.transparency or 0.35) + 0.1, 0, 1)
	follow()
	return amb
end
function fx.shadow(inst, opt)
	opt = opt or {}
	if not opt.glow and Library.Shadows and Build.IconAsset.fx_shadowsq then return squareShadow(inst, opt) end
	if FLAT and not opt.force then return Instance.new("ImageLabel") end
	local s = (opt.radius or 10) / 10
	local spread = 24 * s
	local l, r, t, b = padOf(inst)
	local img = Instance.new("ImageLabel")
	img.Name = opt.glow and "\0Glow" or "\0Shadow"
	img.BackgroundTransparency, img.BorderSizePixel = 1, 0
	img.Image = Build.IconAsset[opt.glow and "fx_glow" or "fx_shadow"] or ""
	img.ScaleType = Enum.ScaleType.Slice
	img.SliceCenter = SLICE
	img.SliceScale = s
	img.Position = UDim2.new(0, -spread - l, 0, -spread - t)
	img.Size = UDim2.new(1, spread * 2 + l + r, 1, spread * 2 + t + b)
	img.ImageTransparency = opt.transparency or 0.35
	img.ZIndex = 0
	img.Parent = inst
	local c = opt.color or (opt.glow and "Accent" or "Shadow")
	if type(c) == "string" then Library:AddToTheme(img, { ImageColor3 = c }) else img.ImageColor3 = c end
	return img
end
-- an accent halo that starts hidden; fx.glowTo(img, on) fades it
function fx.glow(inst, radius, strength)
	if FLAT then return nil end
	local g = fx.shadow(inst, { radius = radius, glow = true, transparency = 1 })
	g:SetAttribute("On", 1 - (strength or 0.55))
	return g
end
function fx.glowTo(g, on, t) if g then fx.tween(g, { ImageTransparency = on and g:GetAttribute("On") or 1 }, t or 0.25) end end

-- top-lit 3D look: the fill darkens towards the bottom and the border is bright on top, fading out downwards
function fx.bevel(inst, depth, force)
	if FLAT and not force then return end
	depth = depth or 0.14
	if not inst:FindFirstChildOfClass("UIGradient") then
		local g = Instance.new("UIGradient")
		g.Name = "\0Bevel"
		g.Rotation = 90
		local d = math.floor(255 * (1 - depth))
		g.Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(d, d, d))
		g.Parent = inst
	end
	local st = inst:FindFirstChildOfClass("UIStroke")
	if st and not st:FindFirstChildOfClass("UIGradient") then
		Library:AddToTheme(st, { Color = "Highlight" })
		local g = Instance.new("UIGradient")
		g.Name = "\0Bevel"
		g.Rotation = 90
		g.Color = ColorSequence.new(Color3.new(1, 1, 1), Color3.fromRGB(110, 110, 110))
		g.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(0.5, 0.55), NumberSequenceKeypoint.new(1, 0.7) })
		g.Parent = st
	end
end

-- fx.hover(button, enter, leave): the click overlay TextButton receives the mouse (it covers the element)
function fx.hover(button, enter, leave)
	Library:Connect(button.MouseEnter, enter)
	Library:Connect(button.MouseLeave, leave)
end

-- fx.press(inst, button, depth): the element sinks (UIScale) while held
function fx.press(inst, button, depth)
	local sc = Instance.new("UIScale")
	sc.Name = "\0Press"
	sc.Parent = inst
	Library:Connect(button.MouseButton1Down, function() fx.tween(sc, { Scale = depth or 0.965 }, 0.08) end)
	local function up() fx.tween(sc, { Scale = 1 }, 0.35, Enum.EasingStyle.Back) end
	Library:Connect(button.MouseButton1Up, up)
	Library:Connect(button.MouseLeave, up)
	return sc
end

-- fx.ripple(inst, x, y): a soft accent disc grows from the click point and fades (clipped to the element's rectangle)
function fx.ripple(inst, x, y)
	if FLAT or not Library.Animations then return end
	local clip = inst:FindFirstChild("FxRipples")   -- (a "\0" name reads back empty, so this one is findable)
	if not clip then
		clip = Instance.new("Frame")
		clip.Name = "FxRipples"
		clip.BackgroundTransparency, clip.BorderSizePixel = 1, 0
		clip.Size = UDim2.fromScale(1, 1)
		clip.ClipsDescendants = true
		clip.ZIndex = 1
		clip.Parent = inst
	end
	local a, s = inst.AbsolutePosition, inst.AbsoluteSize
	local d = Instance.new("ImageLabel")
	d.BackgroundTransparency, d.BorderSizePixel = 1, 0
	d.Image = Build.IconAsset.fx_ripple or ""
	d.AnchorPoint = Vector2.new(0.5, 0.5)
	d.Position = UDim2.fromScale((x - a.X) / math.max(s.X, 1), (y - a.Y) / math.max(s.Y, 1))
	d.Size = UDim2.new(0, 0, 0, 0)
	d.ImageColor3 = Library.Theme.Accent
	d.ImageTransparency = 0.55
	local ar = Instance.new("UIAspectRatioConstraint")
	ar.DominantAxis = Enum.DominantAxis.Width
	ar.Parent = d
	d.Parent = clip
	fx.tween(d, { Size = UDim2.fromScale(2.4, 2.4), ImageTransparency = 1 }, 0.55)
	task.delay(0.6, function() pcall(function() d:Destroy() end) end)
end


-- ===== runtime/elements1.lua =====
-- uilibAurora runtime part 2: Toggle, Button, Label (+ the add-on row for colorpicker / keybind). Uses Library, Build, field, click, listLayout from core.

-- right-aligned row for the add-ons (colour swatches, key pills) of a toggle / label row
local function addonRow(rowRoot, rightMargin)
	local row = Instance.new("Frame")
	row.Name = "\0"
	row.BackgroundTransparency = 1
	row.AnchorPoint = Vector2.new(1, 0.5)
	row.Position = UDim2.new(1, -rightMargin, 0.5, 0)
	row.Size = UDim2.new(0, 0, 0, 15)
	row.AutomaticSize = Enum.AutomaticSize.X
	row.ZIndex = 3
	row.Parent = rowRoot
	local l = Library.listLayout(row, 4, Enum.FillDirection.Horizontal)
	l.HorizontalAlignment = Enum.HorizontalAlignment.Right
	l.VerticalAlignment = Enum.VerticalAlignment.Center
	l.SortOrder = Enum.SortOrder.LayoutOrder
	return row
end
Library.addonRow = addonRow

local function tooltipFor(inst, text) end   -- tooltips come with the HUD phase

-- ---- Toggle ----
function Library:Toggle(Data)
	Data = Data or {}
	local section = self
	local flag = field(Data, "Flag", "flag") or Library:NextFlag()
	local fx = Library.fx
	local T = Build.Toggle(section.Items["Content"].Instance)
	T.Root.Size = UDim2.new(1, 0, 0, 19)
	T.label.Text = tostring(field(Data, "Name", "name") or "Toggle")
	Library.attachTooltip(T.Root, field(Data, "Tooltip", "tooltip"))
	Library.regSearch(section, T.Root, T.label.Text)
	T.label.Size = UDim2.new(1, -18, 0, 15)
	local risky = field(Data, "Risky", "risky")
	local callback = field(Data, "Callback", "callback")
	local toggle = { Value = false, Flag = flag, Listeners = {}, Items = { Toggle = Library.Wrap(T.Root), Text = Library.Wrap(T.label) }, Section = section }
	toggle.Count = 0
	-- the checkbox: box = the 9 px square (Inline off, Accent on), check = the inner square, which pops in when it turns on
	T.check.AnchorPoint, T.check.Position = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5)
	T.check.Size = UDim2.fromScale(1, 1)
	local checkScale = Instance.new("UIScale", T.check)
	local hovering = false
	local function paint(instant)
		local on = toggle.Value
		local t = instant and 0 or 0.14
		Library:ChangeItemTheme(T.box, { BackgroundColor3 = on and "Accent" or "Inline" })
		Library:ChangeItemTheme(T.check, { BackgroundColor3 = "Accent" })
		fx.tween(T.box, { BackgroundColor3 = on and Library.Theme.Accent or (hovering and Library.Theme["Element Hover"] or Library.Theme.Inline) }, t)
		fx.tween(T.check, { BackgroundTransparency = on and 0 or 1 }, t)
		checkScale.Scale = on and 0.4 or 1
		if on then fx.tween(checkScale, { Scale = 1 }, instant and 0 or 0.18, Enum.EasingStyle.Back) end
		if risky then T.label.TextColor3 = Library.Theme.Risky end
	end
	local function set(v, silent)
		toggle.Value = v and true or false
		Library.Flags[flag] = toggle.Value
		paint()
		for _, l in toggle.Listeners do l(toggle.Value) end
		if not silent and callback then Library:SafeCall(callback, toggle.Value) end
	end
	function toggle:Set(v) set(v) end
	function toggle:Get() return toggle.Value end
	function toggle:SetVisibility(b) T.Root.Visible = b end
	Library.SetFlags[flag] = function(v) set(v) end
	paint(true)   -- (the flag is written by the first Set, like the old lib)
	local btn = click(T.Root, function() set(not toggle.Value) end)
	-- hover: the label brightens and an off box lightens
	fx.hover(btn, function()
		hovering = true
		if not risky then fx.tween(T.label, { TextColor3 = Library.Theme["Bright Text"] }, 0.12) end
		if not toggle.Value then fx.tween(T.box, { BackgroundColor3 = Library.Theme["Element Hover"] }, 0.12) end
	end, function()
		hovering = false
		if not risky then fx.tween(T.label, { TextColor3 = Library.Theme.Text }, 0.18) end
		if not toggle.Value then fx.tween(T.box, { BackgroundColor3 = Library.Theme.Inline }, 0.18) end
	end)
	if field(Data, "Default", "default") then set(true) end

	-- add-ons: :Colorpicker / :Keybind put their widgets in the row left of the box
	local row
	local function addons() if not row then row = addonRow(T.Root, 2) end return row end
	function toggle:Colorpicker(d) return Library.AddColorpicker(toggle, addons(), d) end
	function toggle:Keybind(d) return Library.AddKeybind(toggle, addons(), d, toggle) end
	return toggle
end

-- a button: hover lightens it, a press sinks it a little and flashes its edge in the accent colour
function Library.raiseButton(root, btn)
	local fx = Library.fx
	fx.bevel(root, 0.16)
	local sh = fx.shadow(root, { radius = 8, transparency = 0.5 })
	fx.press(root, btn)
	fx.hover(btn, function()
		fx.tween(root, { BackgroundColor3 = Library.Theme["Element Hover"] }, 0.15)
		fx.tween(sh, { ImageTransparency = 0.25 }, 0.15)
	end, function()
		fx.tween(root, { BackgroundColor3 = Library.Theme.Element }, 0.25)
		fx.tween(sh, { ImageTransparency = 0.5 }, 0.25)
	end)
	local st = root:FindFirstChildOfClass("UIStroke")
	if st then
		Library:Connect(btn.MouseButton1Down, function() st.Color = Library.Theme.Accent end)
		Library:Connect(btn.MouseButton1Up, function() fx.tween(st, { Color = Library.Theme.Outline }, 0.3) end)
		Library:Connect(btn.MouseLeave, function() fx.tween(st, { Color = Library.Theme.Outline }, 0.3) end)
	end
end

-- ---- Button (+ SubButton: a second button in the same row) ----
-- ---- confirmation for risky buttons ----
-- A button whose name says it overwrites, deletes, resets, leaves the server or spends money asks first, in a small box on top of
-- the button itself: the action, what it does, and confirm / cancel. Data.Confirm on a Button: true = always ask, a string = ask
-- with that message, false = never ask; nil = decided from the name by Library.RiskyButtons.
-- { pattern on the lowercased name, the message, red (destructive) confirm }
Library.RiskyButtons = {
	{ "^delete", "This deletes it for good.", true },
	{ "^unload", "The menu and every feature are switched off.", true },
	{ "^clear", "This cannot be undone.", true },
	{ "^reset .*stat", "The counters are set back to zero.", true },
	{ "^reset session", "The counters are set back to zero.", true },
	{ "^save config", "The saved file is overwritten with your current settings.", false },
	{ "^save ", "The saved one is overwritten.", false },
	{ "^load config", "Your current settings are replaced by the config.", false },
	{ "^load selected", "Your current settings are replaced.", false },
	{ "^import", "Your current settings are replaced by the imported ones.", false },
	{ "autoload", "This changes which config loads when the script starts.", false },
	{ "server hop", "You leave this server.", false },
	{ "^join", "You leave this server.", false },
	{ "^buy", "This spends in-game money.", false },
	{ "^steal", "Other players or the game may notice this.", false },
}
function Library.riskyMessage(name)
	local n = tostring(name or ""):lower()
	for _, r in Library.RiskyButtons do
		if n:find(r[1]) then return r[2], r[3] end
	end
	return nil
end

-- Library:Confirm({ Title, Text, Yes, No, Danger, Anchor, Root }, onYes): the ConfirmBox of the design sheet (Build.ConfirmBox:
-- double edge, accent line, warning icon, title, message, cancel / confirm) sits right above Anchor (the button) inside Root (the
-- window), as wide as the button, with its notch pointing at it; below the button when there is no room above; with no Anchor it is
-- centred in Root. Danger paints the line, the icon and confirm in Risky. Escape or a click anywhere else cancels. Returns { Close }.
local openConfirm
function Library:Confirm(Data, onYes)
	Data = Data or {}
	local fx = Library.fx
	if openConfirm then openConfirm(false) end
	local root = Data.Root or (Library.Windows[1] and Library.Windows[1]._W.Root) or Library.Holder.Instance
	local anchor = Data.Anchor
	local C = Build.ConfirmBox(root)
	local box = C.Root
	box.Name = "ConfirmBox"
	box.ZIndex = 3001
	local H0 = box.Size.Y.Offset
	local H = H0
	C.title.Text = tostring(Data.Title or "Are you sure?")
	C.title.FontFace = Library.FontBold
	C.title.TextTruncate = Enum.TextTruncate.AtEnd
	C.text.Text = tostring(Data.Text or "")
	C.text.TextWrapped, C.text.TextYAlignment = true, Enum.TextYAlignment.Top
	C.cancelText.Text = tostring(Data.No or "cancel")
	C.confirmText.Text = tostring(Data.Yes or "confirm")
	C.confirmText.FontFace = Library.FontBold
	if Data.Danger then
		Library.themed(C.line, "BackgroundColor3", "Risky")
		Library.themed(C.icon, "ImageColor3", "Risky")
		Library.themed(C.confirm, "BackgroundColor3", "Risky")
	end
	-- where: above the button (window coordinates, without the window's DPI scale), else below it, else centred
	local sc = root:FindFirstChildOfClass("UIScale")
	local k = (sc and sc.Scale > 0) and sc.Scale or 1
	local below = false
	-- the box is as tall as its message: the text's own height (wrapped at the box width) replaces the design's two lines
	local textH0 = C.text.Size.Y.Offset
	local function fitHeight(W)
		local tw = W + C.text.Size.X.Offset   -- the text spans the box minus its margins (Size.X = 1, -m)
		local okB, bounds = pcall(function()
			local p = Instance.new("GetTextBoundsParams")
			p.Text, p.Font, p.Size, p.Width = C.text.Text, C.text.FontFace, C.text.TextSize, tw
			return game:GetService("TextService"):GetTextBoundsAsync(p)
		end)
		local th = (okB and bounds) and math.ceil(bounds.Y) or textH0
		if C.text.Text == "" then th = 0 end
		C.text.Size = UDim2.new(C.text.Size.X.Scale, C.text.Size.X.Offset, 0, th)
		H = H0 - textH0 + th + 6   -- (+6: 10 px between the message and the buttons)
		box.Size = UDim2.fromOffset(W, H)
	end
	fx.shadow(box, { radius = 12, transparency = 0.15 })
	fx.bevel(C.confirm, 0.18, true)
	fx.bevel(C.cancel, 0.14, true)
	if anchor then
		local W = math.max(anchor.AbsoluteSize.X / k, 220)
		fitHeight(W)
		local ra, a, s = root.AbsolutePosition, anchor.AbsolutePosition, anchor.AbsoluteSize
		local x, top = (a.X - ra.X) / k, (a.Y - ra.Y) / k
		local y = top - H - 6
		if y < 4 then y, below = top + s.Y / k + 6, true end
		box.Position = UDim2.fromOffset(x, y)
		-- the window can shift its children (padding): measure where the box landed and correct by the difference
		local wantX, wantY = ra.X + x * k, ra.Y + y * k
		local got = box.AbsolutePosition
		box.Position = UDim2.fromOffset(x + (wantX - got.X) / k, y + (wantY - got.Y) / k)
		-- the notch: a turned square of the box colour on the edge facing the button, over the button's middle (inside the box)
		local cx = math.clamp((a.X + s.X / 2 - box.AbsolutePosition.X) / k, 14, W - 14)
		C.caret.AnchorPoint, C.caret.Rotation = Vector2.new(0.5, 0.5), 45
		C.caret.Position = below and UDim2.new(0, cx, 0, 0) or UDim2.new(0, cx, 1, 0)
		C.caret.ZIndex = 3
	else
		fitHeight(box.Size.X.Offset)
		C.caret.Visible = false
		box.AnchorPoint, box.Position = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5)
	end
	local done = false
	local conns = {}
	local function close(yes)
		if done then return end
		done = true
		openConfirm = nil
		for _, c in conns do pcall(function() c:Disconnect() end) end
		fx.tween(box, { Position = box.Position + UDim2.fromOffset(0, below and 4 or -4) }, 0.1)
		task.delay(0.1, function() pcall(function() box:Destroy() end) end)
		if yes and onYes then task.spawn(function() Library:SafeCall(onYes) end) end
	end
	openConfirm = close
	-- the two buttons: hover lightens them, a press flashes their edge in the accent colour
	local function wire(frame, label, yes)
		local base = frame.BackgroundColor3
		local edge = frame:FindFirstChildOfClass("UIStroke")
		local b = click(frame, function() close(yes) end)
		conns[#conns + 1] = b.MouseEnter:Connect(function()
			fx.tween(frame, { BackgroundColor3 = base:Lerp(Color3.new(1, 1, 1), 0.1) }, 0.1)
			if not yes then fx.tween(label, { TextColor3 = Library.Theme["Bright Text"] }, 0.1) end
		end)
		conns[#conns + 1] = b.MouseLeave:Connect(function()
			fx.tween(frame, { BackgroundColor3 = base }, 0.12)
			if not yes then fx.tween(label, { TextColor3 = Library.Theme.Text }, 0.12) end
		end)
		if edge then conns[#conns + 1] = b.MouseButton1Down:Connect(function() edge.Color = Library.Theme.Accent end) end
	end
	wire(C.confirm, C.confirmText, true)
	wire(C.cancel, C.cancelText, false)
	-- Escape, or a click outside the box (the click that opened it is over by now)
	local opened = os.clock()
	conns[#conns + 1] = UserInputService.InputBegan:Connect(function(i)
		if i.KeyCode == Enum.KeyCode.Escape then close(false) return end
		if (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) and os.clock() - opened > 0.05
			and not Library:IsMouseOverFrame(box) then
			close(false)
		end
	end)
	-- in: a short slide toward the button
	local pos = box.Position
	box.Position = pos + UDim2.fromOffset(0, below and 6 or -6)
	fx.tween(box, { Position = pos }, 0.15)
	return { Close = function() close(false) end }
end

-- what a button click does: straight away, or after the confirmation when the button is risky
function Library.guardedClick(section, anchor, name, confirm, fn)
	local msg, danger
	if confirm == nil then msg, danger = Library.riskyMessage(name)
	elseif confirm == true then msg = "This cannot be undone."
	elseif type(confirm) == "string" then msg = confirm end
	return function()
		if not fn then return end
		if not msg then Library:SafeCall(fn) return end
		local root = section and section.Window and section.Window._W and section.Window._W.Root
		Library:Confirm({ Title = tostring(name) .. "?", Text = msg, Danger = danger, Anchor = anchor, Root = root }, fn)
	end
end

function Library:Button(Data)
	Data = Data or {}
	local section = self
	local B = Build.Button(section.Items["Content"].Instance)
	B.Root.Size = UDim2.new(1, 0, 0, 22)
	B.label.Text = tostring(field(Data, "Name", "name") or "Button")
	Library.attachTooltip(B.Root, field(Data, "Tooltip", "tooltip"))
	Library.regSearch(section, B.Root, B.label.Text)
	local callback = field(Data, "Callback", "callback")
	if field(Data, "Risky", "risky") then B.label.TextColor3 = Library.Theme.Risky end
	local btn = click(B.Root, Library.guardedClick(section, B.Root, B.label.Text, field(Data, "Confirm", "confirm"), callback))
	Library.raiseButton(B.Root, btn)
	local obj = { Items = { Button = Library.Wrap(B.Root) }, Section = section }
	function obj:SetVisibility(b) B.Root.Visible = b end
	function obj:SubButton(d)
		d = d or {}
		-- two buttons share the row: this one is halved and a new one is placed beside it
		B.Root.Size = UDim2.new(0.5, -2, 0, 22)
		local list = Library.listLayout(B.Root.Parent, 4)
		local sub = Build.Button(section.Items["Content"].Instance)
		sub.Root.Size = UDim2.new(0.5, -2, 0, 22)
		sub.Root.Position = UDim2.new(0.5, 2, 0, 0)
		sub.label.Text = tostring(field(d, "Name", "name") or "Button")
		local cb = field(d, "Callback", "callback")
		Library.raiseButton(sub.Root, click(sub.Root, Library.guardedClick(section, sub.Root, sub.label.Text, field(d, "Confirm", "confirm"), cb)))
		return { SetVisibility = function(_, b) sub.Root.Visible = b end }
	end
	return obj
end

-- ---- Label(Text, Alignment) ----
function Library:Label(Text, Alignment)
	local section = self
	local L = Build.Label(section.Items["Content"].Instance)
	L.Root.Size = UDim2.new(1, 0, 0, 19)
	L.Root.AutomaticSize = Enum.AutomaticSize.Y
	L.text.Position = UDim2.new(0, 18, 0, 0)
	L.text.Size = UDim2.new(1, -20, 0, 0)
	L.text.AutomaticSize = Enum.AutomaticSize.Y
	L.text.TextWrapped = true
	L.text.RichText = true
	L.text.Text = tostring(Text or "Label")
	Library.regSearch(section, L.Root, L.text.Text)
	local a = tostring(Alignment or "Left"):lower()
	L.text.TextXAlignment = a == "center" and Enum.TextXAlignment.Center or a == "right" and Enum.TextXAlignment.Right or Enum.TextXAlignment.Left
	local label = { Items = { Label = Library.Wrap(L.Root), Text = Library.Wrap(L.text) }, Section = section }
	function label:SetVisibility(b) L.Root.Visible = b end
	function label:SetText(t) L.text.Text = tostring(t) end
	local row
	local function addons() if not row then row = addonRow(L.Root, 0) L.text.Size = UDim2.new(1, -80, 0, 0) end return row end
	function label:Colorpicker(d) return Library.AddColorpicker(label, addons(), d) end
	function label:Keybind(d) return Library.AddKeybind(label, addons(), d, nil) end
	return label
end


-- ===== runtime/elements2.lua =====
-- uilibAurora runtime part 3: Slider, Dropdown (single / multi), Listbox, Textbox. Behaviour = uilibnewBlxStrike.lua (flags, Set/Get, callbacks).

local function setText(inst, t) inst.Text = t end

-- a field (flat in Aurora): returns the accent glow for focus / open, which the flat style does not have (nil)
function Library.insetField(f)
	return Library.fx.glow(f, 8, 0.6)
end

-- ---- Slider ----
function Library:Slider(Data)
	Data = Data or {}
	local section = self
	local flag = field(Data, "Flag", "flag") or Library:NextFlag()
	local min, max = field(Data, "Min", "min") or 0, field(Data, "Max", "max") or 100
	local step = field(Data, "Decimals", "decimals") or 1
	local suffix = field(Data, "Suffix", "suffix") or ""
	local callback = field(Data, "Callback", "callback")
	local fx = Library.fx
	local T = Build.Slider(section.Items["Content"].Instance)
	T.Root.Size = UDim2.new(1, 0, 0, 44)
	T.label.Text = tostring(field(Data, "Name", "name") or "Slider")
	Library.attachTooltip(T.Root, field(Data, "Tooltip", "tooltip"))
	Library.regSearch(section, T.Root, T.label.Text)
	local slider = { Value = min, Flag = flag, Items = { Slider = Library.Wrap(T.Root) }, Section = section }
	-- flat imgui bar: no knob; while hovered / dragged the value brightens and the bar's edge turns to the accent
	local trackStroke = T.track:FindFirstChildOfClass("UIStroke")
	T.fill.Position = UDim2.new()   -- the design's 1 px inset is for a fill 2 px smaller than the track; this fill is sized in scale of the whole track
	T.knob.Visible = false
	local knobScale = Instance.new("UIScale", T.knob)
	local fillGlow = nil
	local function paint()
		local frac = max > min and (slider.Value - min) / (max - min) or 0
		Library:TweenTo(T.fill, { Size = UDim2.new(frac, 0, 1, 0) }, 0.12)
		Library:TweenTo(T.knob, { Position = UDim2.new(frac, 0, 0.5, 0) }, 0.12)
		T.value.Text = tostring(slider.Value) .. suffix
	end
	local function set(v)
		v = tonumber(v)
		if not v then return end
		v = math.floor(v * (1 / step)) / (1 / step)
		slider.Value = math.clamp(v, min, max)
		Library.Flags[flag] = slider.Value
		paint()
		if callback then Library:SafeCall(callback, slider.Value) end
	end
	function slider:Set(v) set(v) end
	function slider:Get() return slider.Value end
	function slider:SetVisibility(b) T.Root.Visible = b end
	local dragging = false
	local function fromX(x)
		local w = T.track.AbsoluteSize.X
		set(min + (max - min) * math.clamp((x - T.track.AbsolutePosition.X) / math.max(w, 1), 0, 1))
	end
	local hit = Instance.new("TextButton")
	hit.BackgroundTransparency, hit.Text, hit.AutoButtonColor = 1, "", false
	hit.Size, hit.Position, hit.ZIndex = UDim2.new(1, 0, 0, 14), UDim2.new(0, 0, 0, -4), 5
	hit.Parent = T.track
	-- the knob grows while hovered / dragged, the fill glows
	local hovering = false
	local function lit()
		local on = hovering or dragging
		fx.tween(T.value, { TextColor3 = on and Library.Theme["Bright Text"] or Library.Theme["Dim Text"] }, 0.15)
		if trackStroke then fx.tween(trackStroke, { Color = on and Library.Theme.Accent or Library.Theme.Outline }, 0.15) end
	end
	fx.hover(hit, function() hovering = true lit() end, function() hovering = false lit() end)
	-- the - / + beside the bar step the value (one Decimals step, at least 1 % of the range)
	local function nudge(dir)
		local inc = math.max(step, (max - min) / 100)
		set(slider.Value + dir * inc)
	end
	for _, b in { { T.minus, -1 }, { T.plus, 1 } } do
		local lab, dir = b[1], b[2]
		if lab then
			local bt = click(lab, function() nudge(dir) end)
			fx.hover(bt, function() fx.tween(lab, { TextColor3 = Library.Theme.Accent }, 0.1) end, function() fx.tween(lab, { TextColor3 = Library.Theme["Dim Text"] }, 0.15) end)
		end
	end
	Library:Connect(hit.InputBegan, function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then dragging = true fromX(i.Position.X) lit() end
	end)
	Library:Connect(UserInputService.InputChanged, function(i)
		if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then fromX(i.Position.X) end
	end)
	Library:Connect(UserInputService.InputEnded, function(i)
		if dragging and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) then dragging = false lit() end
	end)
	set(field(Data, "Default", "default") or 0)
	Library.SetFlags[flag] = set
	return slider
end

-- ---- shared by Dropdown and Listbox: the option store (single / multi) ----
local function optionStore(opts)
	-- opts: multi, makeRow(name) -> { row, text }, onValue(value) (text), callback, flag, container
	local st = { Value = opts.multi and {} or nil, Options = {}, multi = opts.multi }
	local fx = Library.fx
	local function paintRow(o)
		local sel = o.selected
		Library:ChangeItemTheme(o.text, { TextColor3 = sel and "Accent" or "Dim Text" })
		Library:ChangeItemTheme(o.row, { BackgroundColor3 = "Element" })
		o.text.FontFace = sel and Library.FontBold or Library.Font
		fx.tween(o.text, { TextColor3 = sel and Library.Theme.Accent or Library.Theme["Dim Text"], Position = UDim2.new(0, sel and 11 or 7, 0, 2) }, 0.15)
		fx.tween(o.row, { BackgroundTransparency = sel and 0 or 1 }, 0.2)
		if o.bar then fx.tween(o.bar, { Size = UDim2.new(0, 2, 0, sel and 10 or 0) }, 0.15) end
	end
	function st.add(name)
		local r = opts.makeRow(name)
		local o = { row = r.row, text = r.text, bar = r.bar, selected = false }
		st.Options[name] = o
		paintRow(o)
		Library:Connect(r.button.MouseButton1Click, function() st.click(name) end)
		fx.hover(r.button, function() if not o.selected then fx.tween(o.row, { BackgroundTransparency = 0.55 }, 0.12) fx.tween(o.text, { TextColor3 = Library.Theme.Text }, 0.12) end end,
			function() if not o.selected then fx.tween(o.row, { BackgroundTransparency = 1 }, 0.18) fx.tween(o.text, { TextColor3 = Library.Theme["Dim Text"] }, 0.18) end end)
		return o
	end
	function st.remove(name)
		local o = st.Options[name]
		if o then pcall(function() o.row:Destroy() end) st.Options[name] = nil end
	end
	local function fire()
		Library.Flags[opts.flag] = st.Value
		if opts.onValue then opts.onValue(st.Value) end
		if opts.callback then Library:SafeCall(opts.callback, st.Value) end
	end
	function st.click(name)
		local o = st.Options[name]
		if not o then return end
		if st.multi then
			local at = table.find(st.Value, name)
			if at then table.remove(st.Value, at) o.selected = false else table.insert(st.Value, name) o.selected = true end
		elseif o.selected then
			o.selected, st.Value = false, nil
		else
			for _, other in st.Options do other.selected = false paintRow(other) end
			o.selected, st.Value = true, name
		end
		paintRow(o)
		fire()
	end
	function st.set(v)
		if st.multi then
			if type(v) ~= "table" then return end
			st.Value = v
			for _, o in st.Options do o.selected = false end
			for _, name in v do
				local o = st.Options[name]
				if not o then break end
				o.selected = true
			end
			for _, o in st.Options do paintRow(o) end
			Library.Flags[opts.flag] = st.Value
			if opts.onValue then opts.onValue(st.Value) end
			if opts.callback then Library:SafeCall(opts.callback, st.Value) end
		else
			local o = st.Options[v]
			if not o then return end
			for _, other in st.Options do other.selected = false paintRow(other) end
			o.selected = true
			st.Value = v
			Library.Flags[opts.flag] = v
			if opts.onValue then opts.onValue(v) end
			if opts.callback then Library:SafeCall(opts.callback, v) end
		end
	end
	function st.refresh(list)
		for name in st.Options do st.remove(name) end
		for _, name in list do st.add(name) end
		-- the kept selection is shown again on the new rows (flags and callbacks are not touched)
		local keep = st.multi and st.Value or (st.Value and { st.Value } or {})
		for _, name in keep do local o = st.Options[name] if o then o.selected = true paintRow(o) end end
	end
	return st
end

local function optionRow(parentScroll)
	return function(name)
		local O = Build.Option(parentScroll)
		O.Root.Size = UDim2.new(1, 0, 0, 18)
		O.Root.BackgroundTransparency = 1
		O.text.Text = tostring(name)
		O.text.Size = UDim2.new(1, -16, 0, 14)
		O.text.TextTruncate = Enum.TextTruncate.AtEnd
		-- the selected row gets a short accent bar on its left
		local bar = Instance.new("Frame")
		bar.BorderSizePixel = 0
		bar.AnchorPoint, bar.Position, bar.Size = Vector2.new(0, 0.5), UDim2.new(0, 4, 0.5, 0), UDim2.new(0, 2, 0, 0)
		bar.Parent = O.Root
		Library:AddToTheme(bar, { BackgroundColor3 = "Accent" })
			local b = Instance.new("TextButton")
		b.BackgroundTransparency, b.Text, b.Size, b.ZIndex = 1, "", UDim2.fromScale(1, 1), O.Root.ZIndex + 2
		b.Parent = O.Root
		return { row = O.Root, text = O.text, button = b, bar = bar }
	end
end

-- ---- Dropdown ----
function Library:Dropdown(Data)
	Data = Data or {}
	local section = self
	local flag = field(Data, "Flag", "flag") or Library:NextFlag()
	local multi = field(Data, "Multi", "multi") and true or false
	local maxSize = field(Data, "MaxSize", "maxsize") or 75
	local callback = field(Data, "Callback", "callback")
	local fx = Library.fx
	local T = Build.Dropdown(section.Items["Content"].Instance)
	T.Root.Size = UDim2.new(1, 0, 0, 42)
	T.label.Text = tostring(field(Data, "Name", "name") or "Dropdown")
	Library.attachTooltip(T.Root, field(Data, "Tooltip", "tooltip"))
	Library.regSearch(section, T.Root, T.label.Text)
	T.value.Text = "--"
	T.value.TextTruncate = Enum.TextTruncate.AtEnd
	T.value.Size = UDim2.new(1, -26, 0, 14)
	local winRoot = Library.popupRoot(section)
	local P = Build.Panel(winRoot)
	P.Root.Visible = false
	P.Root.ZIndex = 1000
	P.Root.Size = UDim2.new(0, 212, 0, 60)
	fx.shadow(P.Root, { radius = 10, transparency = 0.15 })
	fx.bevel(P.Root, 0.08)
	local fieldGlow = Library.insetField(T.field)
	local scroll = Instance.new("ScrollingFrame")
	scroll.BackgroundTransparency, scroll.BorderSizePixel = 1, 0
	scroll.ScrollBarThickness, scroll.ScrollBarImageColor3 = 2, Library.Theme.Inline
	scroll.CanvasSize, scroll.AutomaticCanvasSize = UDim2.new(), Enum.AutomaticSize.Y
	scroll.Size, scroll.ZIndex = UDim2.fromScale(1, 1), 1001
	scroll.Parent = P.rows
	Library.listLayout(scroll, 0)
	local dd = { Flag = flag, Items = { Dropdown = Library.Wrap(T.Root) }, Section = section }
	local store = optionStore({
		multi = multi, flag = flag, callback = callback, makeRow = optionRow(scroll),
		onValue = function(v)
			if multi then T.value.Text = #v > 0 and table.concat(v, ", ") or "--" else T.value.Text = v and tostring(v) or "--" end
		end,
	})
	local open, debounce = false, false
	-- the list unrolls downwards from the field (height tween), and rolls back up before it hides
	local function target()
		local s = T.field.AbsoluteSize
		local count = 0 for _ in store.Options do count += 1 end
		return s.X, math.min(count * 18 + 4, maxSize + 4)
	end
	local openToken = 0
	local function setOpen(b)
		open = b
		openToken += 1
		local my = openToken
		fx.tween(T.chevron, { Rotation = b and 180 or 0 }, 0.18)
		fx.glowTo(fieldGlow, b)
		local w, h = target()
		local sc = winRoot:FindFirstChildOfClass("UIScale")
		w = w / (sc and sc.Scale or 1)   -- AbsoluteSize is scaled by the window's UIScale, Size is not
		if b then
			Library.popupAt(P.Root, winRoot, T.field, 4)
			local s = sc and sc.Scale or 1
			local x, below = P.Root.Position.X.Offset / s, P.Root.Position.Y.Offset / s
			-- no room below the field inside the window: the list opens upwards, growing from just above the field
			local fieldH = T.field.AbsoluteSize.Y / s
			if below + h > winRoot.AbsoluteSize.Y / s - 8 then
				P.Root.AnchorPoint = Vector2.new(0, 1)
				P.Root.Position = UDim2.new(0, x, 0, below - fieldH - 8)
			else
				P.Root.AnchorPoint = Vector2.new(0, 0)
				P.Root.Position = UDim2.new(0, x, 0, below)
			end
			if not P.Root.Visible then P.Root.Size = UDim2.new(0, w, 0, 0) end
			P.Root.Visible = true
			fx.tween(P.Root, { Size = UDim2.new(0, w, 0, h) }, 0.18)
			debounce = true
			task.delay(0.1, function() debounce = false end)
		else
			fx.tween(P.Root, { Size = UDim2.new(0, w, 0, 0) }, 0.12).Completed:Connect(function()
				if openToken == my then P.Root.Visible = false end
			end)
		end
	end
	click(T.field, function() setOpen(not open) end)
	Library:Connect(UserInputService.InputBegan, function(i)
		if open and not debounce and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) and not Library:IsMouseOverFrame(P.Root) and not Library:IsMouseOverFrame(T.field) then setOpen(false) end
	end)
	for _, name in field(Data, "Items", "items") or {} do store.add(name) end
	function dd:Set(v) store.set(v) end
	function dd:Get() return store.Value end
	function dd:Add(name) store.add(name) end
	function dd:Remove(name) store.remove(name) end
	function dd:Refresh(list) store.refresh(list) end
	function dd:SetVisibility(b) T.Root.Visible = b if not b then setOpen(false) end end
	local default = field(Data, "Default", "default")
	if default then store.set(default) end
	Library.SetFlags[flag] = function(v) store.set(v) end
	Library.OnUnload = Library.OnUnload or {}
	table.insert(Library.OnUnload, function() pcall(function() P.Root:Destroy() end) end)
	return dd
end

-- ---- Listbox ----
function Library:Listbox(Data)
	Data = Data or {}
	local section = self
	local flag = field(Data, "Flag", "flag") or Library:NextFlag()
	local multi = field(Data, "Multi", "multi") and true or false
	local size = field(Data, "Size", "size") or 175
	local callback = field(Data, "Callback", "callback")
	local T = Build.Listbox(section.Items["Content"].Instance)
	T.Root.Size = UDim2.new(1, 0, 0, size + 22)
	T.field.Size = UDim2.new(1, -20, 0, size)
	Library.insetField(T.field)
	T.label.Text = tostring(field(Data, "Name", "name") or "Listbox")
	Library.attachTooltip(T.Root, field(Data, "Tooltip", "tooltip"))
	Library.regSearch(section, T.Root, T.label.Text)
	local scroll = Instance.new("ScrollingFrame")
	scroll.BackgroundTransparency, scroll.BorderSizePixel = 1, 0
	scroll.ScrollBarThickness, scroll.ScrollBarImageColor3 = 2, Library.Theme.Inline
	scroll.CanvasSize, scroll.AutomaticCanvasSize = UDim2.new(), Enum.AutomaticSize.Y
	scroll.Size = UDim2.fromScale(1, 1)
	scroll.Parent = T.rows
	Library.listLayout(scroll, 0)
	local lb = { Flag = flag, Items = { Listbox = Library.Wrap(T.Root) }, Section = section }
	local store = optionStore({ multi = multi, flag = flag, callback = callback, makeRow = optionRow(scroll) })
	for _, name in field(Data, "Items", "items") or {} do store.add(name) end
	function lb:Set(v) store.set(v) end
	function lb:Get() return store.Value end
	function lb:Add(name) store.add(name) end
	function lb:Remove(name) store.remove(name) end
	function lb:Refresh(list) store.refresh(list) end
	function lb:SetVisibility(b) T.Root.Visible = b end
	Library.SetFlags[flag] = function(v) store.set(v) end
	return lb
end

-- ---- Textbox ----
function Library:Textbox(Data)
	Data = Data or {}
	local section = self
	local flag = field(Data, "Flag", "flag") or Library:NextFlag()
	local callback = field(Data, "Callback", "callback")
	local T = Build.Textbox(section.Items["Content"].Instance)
	T.Root.Size = UDim2.new(1, 0, 0, 42)
	local glow = Library.insetField(T.field)
	local fieldStroke = T.field:FindFirstChildOfClass("UIStroke")
	T.label.Text = tostring(field(Data, "Name", "name") or "Textbox")
	Library.attachTooltip(T.Root, field(Data, "Tooltip", "tooltip"))
	Library.regSearch(section, T.Root, T.label.Text)
	T.input.Visible = false
	local box = Instance.new("TextBox")
	box.BackgroundTransparency, box.BorderSizePixel = 1, 0
	box.Size, box.Position = UDim2.new(1, -14, 1, 0), UDim2.new(0, 7, 0, 0)
	box.FontFace, box.TextSize = Library.Font, 12
	box.TextColor3, box.PlaceholderColor3 = Library.Theme.Text, Library.Theme["Dim Text"]
	box.PlaceholderText = tostring(field(Data, "Placeholder", "placeholder") or "...")
	box.TextXAlignment, box.ClearTextOnFocus, box.Text = Enum.TextXAlignment.Left, false, ""
	box.TextTruncate = Enum.TextTruncate.AtEnd
	box.Parent = T.field
	local tb = { Value = "", Flag = flag, Items = { Textbox = Library.Wrap(T.Root) }, Section = section }
	local function set(v)
		tb.Value = tostring(v)
		Library.Flags[flag] = tb.Value
		box.Text = tb.Value
		box.TextColor3 = Library.Theme.Text
		if callback then Library:SafeCall(callback, tb.Value) end
	end
	Library:Connect(box.Focused, function()
		box.TextColor3 = Library.Theme.Accent
		Library.fx.glowTo(glow, true)
		if fieldStroke then Library.themed(fieldStroke, "Color", "Accent") end
	end)
	Library:Connect(box.FocusLost, function()
		Library.fx.glowTo(glow, false)
		if fieldStroke then Library.themed(fieldStroke, "Color", "Border") end
		set(box.Text)
	end)
	function tb:Set(v) set(v) end
	function tb:Get() return tb.Value end
	function tb:SetVisibility(b) T.Root.Visible = b end
	set(field(Data, "Default", "default") or "")
	Library.SetFlags[flag] = set
	return tb
end


-- ===== runtime/elements3.lua =====
-- runtime part 4: Colorpicker and Keybind (the add-ons of a Toggle / Label). Behaviour = uilibnewBlxStrike.lua.

local Keys = {
	[Enum.KeyCode.LeftShift] = "LShift", [Enum.KeyCode.RightShift] = "RShift", [Enum.KeyCode.LeftControl] = "LCtrl", [Enum.KeyCode.RightControl] = "RCtrl",
	[Enum.KeyCode.LeftAlt] = "LAlt", [Enum.KeyCode.RightAlt] = "RAlt", [Enum.KeyCode.Return] = "Enter", [Enum.KeyCode.Space] = "Space",
	[Enum.UserInputType.MouseButton1] = "M1", [Enum.UserInputType.MouseButton2] = "M2", [Enum.UserInputType.MouseButton3] = "M3",
}
local function keyText(keyString)
	if not keyString or keyString == "None" or keyString == "[-]" then return "-" end
	for enum, short in Keys do if tostring(enum) == keyString then return short end end
	return (tostring(keyString):gsub("Enum%.KeyCode%.", ""):gsub("Enum%.UserInputType%.", ""))
end

-- ---- Colorpicker ----
local HUE_SEQ = ColorSequence.new({
	ColorSequenceKeypoint.new(0, Color3.fromHSV(0, 1, 1)), ColorSequenceKeypoint.new(1 / 6, Color3.fromHSV(1 / 6, 1, 1)),
	ColorSequenceKeypoint.new(2 / 6, Color3.fromHSV(2 / 6, 1, 1)), ColorSequenceKeypoint.new(3 / 6, Color3.fromHSV(3 / 6, 1, 1)),
	ColorSequenceKeypoint.new(4 / 6, Color3.fromHSV(4 / 6, 1, 1)), ColorSequenceKeypoint.new(5 / 6, Color3.fromHSV(5 / 6, 1, 1)),
	ColorSequenceKeypoint.new(1, Color3.fromHSV(1, 1, 1)),
})
local openPicker   -- only one popup open at a time

function Library.AddColorpicker(owner, row, Data)
	Data = Data or {}
	local flag = field(Data, "Flag", "flag") or Library:NextFlag()
	local callback = field(Data, "Callback", "callback")
	local S = Build.Swatch(row)
	S.Root.LayoutOrder = 2
	S.Root.Size = UDim2.new(0, 18, 0, 9)
	-- the swatch's own background shows through a transparent colour: a neutral tone, not the accent
	Library:ChangeItemTheme(S.Root, { BackgroundColor3 = "Inline" })
	S.Root.BackgroundColor3 = Library.Theme.Inline
	Library.fx.shadow(S.Root, { radius = 5, transparency = 0.45 })
	local winRoot = Library.popupRoot(owner.Section)
	local P = Build.ColorPopup(winRoot)
	P.Root.Visible, P.Root.ZIndex = false, 1000
	Library.fx.shadow(P.Root, { radius = 12, transparency = 0.1 })
	Library.fx.bevel(P.Root, 0.08)
	local popScale = Instance.new("UIScale", P.Root)
	local cp = { Flag = flag, Color = Color3.new(1, 1, 1), Alpha = 0, Hue = 0, Sat = 0, Val = 1, Items = {} }
	cp.Items.Swatch = Library.Wrap(S.Root)
	Library.Flags[flag] = {}

	-- the square: hue colour + white-to-clear (left to right) + clear-to-black (top to bottom)
	P.sv.BackgroundColor3 = Color3.fromHSV(0, 1, 1)
	local w = Instance.new("Frame")
	w.BackgroundColor3, w.BorderSizePixel, w.Size, w.ZIndex = Color3.new(1, 1, 1), 0, UDim2.fromScale(1, 1), P.sv.ZIndex + 1
	w.Parent = P.sv
	-- (square: imgui)
	local g1 = Instance.new("UIGradient", w) g1.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0), NumberSequenceKeypoint.new(1, 1) })
	local b = Instance.new("Frame")
	b.BackgroundColor3, b.BorderSizePixel, b.Size, b.ZIndex = Color3.new(0, 0, 0), 0, UDim2.fromScale(1, 1), P.sv.ZIndex + 2
	b.Parent = P.sv
	-- (square: imgui)
	local g2 = Instance.new("UIGradient", b) g2.Rotation = 90 g2.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(1, 0) })
	P.svCursor.ZIndex = 10
	P.svCursor.Parent = P.sv
	local hg = Instance.new("UIGradient", P.hue) hg.Color = HUE_SEQ
	P.hue.BackgroundColor3 = Color3.new(1, 1, 1)
	P.hueCursor.ZIndex = 5
	P.alphaCursor.ZIndex = 5
	local ag = Instance.new("UIGradient", P.alpha)
	local hexBox = Instance.new("TextBox")
	hexBox.BackgroundTransparency, hexBox.BorderSizePixel, hexBox.Size, hexBox.Position = 1, 0, UDim2.new(1, -16, 1, 0), UDim2.new(0, 8, 0, 0)
	hexBox.FontFace, hexBox.TextSize, hexBox.TextColor3, hexBox.TextXAlignment, hexBox.ClearTextOnFocus = Library.Font, 12, Library.Theme.Text, Enum.TextXAlignment.Left, false
	hexBox.Parent = P.hexField
	P.hex.Visible = false

	local function update(silent)
		cp.Color = Color3.fromHSV(cp.Hue, cp.Sat, cp.Val)
		-- the design binds these to the Accent theme colour; Library.themed with a Color3 drops that binding, otherwise the next theme
		-- change (every config load applies the theme) would paint every swatch in the accent colour
		Library.themed(S.color, "BackgroundColor3", cp.Color)
		S.color.BackgroundTransparency = cp.Alpha * 0.8
		Library.themed(P.preview, "BackgroundColor3", cp.Color)
		P.sv.BackgroundColor3 = Color3.fromHSV(cp.Hue, 1, 1)
		P.svCursor.Position = UDim2.new(cp.Sat, -3, 1 - cp.Val, -3)
		P.hueCursor.Position = UDim2.new(cp.Hue, -1, 0, -1)
		P.alphaCursor.Position = UDim2.new(cp.Alpha, -1, 0, -1)
		ag.Color = ColorSequence.new(cp.Color, Library.Theme.Inline)
		hexBox.Text = "#" .. cp.Color:ToHex():upper()
		Library.Flags[flag] = { HexValue = cp.Color:ToHex(), Color = cp.Color, Alpha = cp.Alpha, Flag = flag }
		if not silent and callback then Library:SafeCall(callback, cp.Color, cp.Alpha) end
	end
	local function set(color, alpha)
		if type(color) == "string" then local ok, c = pcall(Color3.fromHex, color) if not ok then return end color = c end
		if typeof(color) ~= "Color3" then return end
		cp.Hue, cp.Sat, cp.Val = color:ToHSV()
		cp.Alpha = math.clamp(tonumber(alpha) or 0, 0, 1)
		update()
	end
	function cp:Set(c, a) set(c, a) end
	function cp:Get() return cp.Color, cp.Alpha end
	function cp:SetVisibility(v) S.Root.Visible = v end

	-- popup
	local open, debounce = false, false
	local function setOpen(v)
		if v and openPicker and openPicker ~= setOpen then openPicker(false) end
		open = v
		P.Root.Visible = v
		openPicker = v and setOpen or nil
		if v then
			Library.popupAt(P.Root, winRoot, S.Root, 6)
			local x = math.min(P.Root.Position.X.Offset, winRoot.AbsoluteSize.X - 206)
			P.Root.Position = UDim2.new(0, x, 0, math.min(P.Root.Position.Y.Offset, winRoot.AbsoluteSize.Y - 326))
			-- pops in from slightly smaller
			popScale.Scale = 0.9
			Library.fx.tween(popScale, { Scale = 1 }, 0.3, Enum.EasingStyle.Back)
			debounce = true
			task.delay(0.1, function() debounce = false end)
		end
	end
	click(S.Root, function() setOpen(not open) end)
	Library:Connect(UserInputService.InputBegan, function(i)
		if open and not debounce and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) and not Library:IsMouseOverFrame(P.Root) and not Library:IsMouseOverFrame(S.Root) then setOpen(false) end
	end)
	local drag
	local function bind(frame, kind)
		Library:Connect(frame.InputBegan, function(i)
			if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then drag = kind end
		end)
	end
	bind(P.sv, "sv") bind(P.hue, "hue") bind(P.alpha, "alpha")
	local function apply(pos)
		if drag == "sv" then
			cp.Sat = math.clamp((pos.X - P.sv.AbsolutePosition.X) / P.sv.AbsoluteSize.X, 0, 1)
			cp.Val = 1 - math.clamp((pos.Y - P.sv.AbsolutePosition.Y) / P.sv.AbsoluteSize.Y, 0, 1)
		elseif drag == "hue" then
			cp.Hue = math.clamp((pos.X - P.hue.AbsolutePosition.X) / P.hue.AbsoluteSize.X, 0, 0.999)
		elseif drag == "alpha" then
			cp.Alpha = math.clamp((pos.X - P.alpha.AbsolutePosition.X) / P.alpha.AbsoluteSize.X, 0, 1)
		else return end
		update()
	end
	Library:Connect(UserInputService.InputChanged, function(i)
		if drag and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then apply(i.Position) end
	end)
	Library:Connect(UserInputService.InputBegan, function(i)
		if (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) and open and drag then apply(i.Position) end
	end)
	Library:Connect(UserInputService.InputEnded, function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then drag = nil end
	end)
	Library:Connect(hexBox.FocusLost, function() set(hexBox.Text, cp.Alpha) end)

	-- ---- animation: Rainbow / Fade Alpha (flags <flag>AnimationModeDropdown / AnimationIntensitySlider / AnimationSpeedSlider) ----
	local anim = { mode = nil, speed = 0.2, intensity = 50 }
	local flagMode, flagInt, flagSpeed = flag .. "AnimationModeDropdown", flag .. "AnimationIntensitySlider", flag .. "AnimationSpeedSlider"
	Library.Flags[flagInt], Library.Flags[flagSpeed] = anim.intensity, anim.speed
	local oldColor, oldAlpha
	local function paintAnim()
		for mode, parts in { Rainbow = { P.animRainbow, P.animRainbowText }, ["Fade Alpha"] = { P.animFade, P.animFadeText } } do
			local on = anim.mode == mode
			Library.themed(parts[1], "BackgroundColor3", on and "Accent" or "Element")
			Library.themed(parts[2], "TextColor3", on and Color3.fromRGB(20, 20, 24) or Color3.fromRGB(169, 169, 178))
		end
		P.speedFill.Size = UDim2.new(anim.speed / 5, 0, 1, 0)
		P.speedLabel.Text = string.format("Speed %.2fs", anim.speed)
		P.intensityFill.Size = UDim2.new(anim.intensity / 100, 0, 1, 0)
		P.intensityLabel.Text = string.format("Intensity %d%%", anim.intensity)
	end
	local function setMode(mode)
		if mode ~= "Rainbow" and mode ~= "Fade Alpha" then mode = nil end
		if mode == anim.mode then return end
		if mode and not anim.mode then oldColor, oldAlpha = cp.Color, cp.Alpha end
		local was = anim.mode
		anim.mode = mode
		Library.Flags[flagMode] = mode
		paintAnim()
		if was and not mode and oldColor then set(oldColor, oldAlpha) end   -- the colour from before the animation comes back
	end
	local function setSpeed(v) anim.speed = math.clamp(math.floor((tonumber(v) or 0.2) * 100) / 100, 0, 5) Library.Flags[flagSpeed] = anim.speed paintAnim() end
	local function setIntensity(v) anim.intensity = math.clamp(math.floor(tonumber(v) or 50), 0, 100) Library.Flags[flagInt] = anim.intensity paintAnim() end
	click(P.animRainbow, function() setMode(anim.mode == "Rainbow" and nil or "Rainbow") end)
	click(P.animFade, function() setMode(anim.mode == "Fade Alpha" and nil or "Fade Alpha") end)
	local function trackDrag(track, apply)
		local down = false
		local function at(x) apply(math.clamp((x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1), 0, 1)) end
		local hit = Instance.new("TextButton")
		hit.BackgroundTransparency, hit.Text, hit.Size, hit.Position, hit.ZIndex = 1, "", UDim2.new(1, 0, 0, 16), UDim2.new(0, 0, 0, -6), 6
		hit.Parent = track
		Library:Connect(hit.InputBegan, function(i) if (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) then down = true at(i.Position.X) end end)
		Library:Connect(UserInputService.InputChanged, function(i) if down and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then at(i.Position.X) end end)
		Library:Connect(UserInputService.InputEnded, function(i) if (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) then down = false end end)
	end
	trackDrag(P.speedTrack, function(f) setSpeed(f * 5) end)
	trackDrag(P.intensityTrack, function(f) setIntensity(f * 100) end)
	paintAnim()
	local lastAnim = 0
	Library:Connect(RunService.Heartbeat, function()
		if not anim.mode then return end
		local now = os.clock()
		if now - lastAnim < 1 / 30 then return end
		lastAnim = now
		if anim.mode == "Rainbow" then
			set(Color3.fromHSV(math.abs(math.sin(tick() * anim.speed)), 1, 1), cp.Alpha)
		else
			set(cp.Color, math.clamp(math.abs(math.sin(tick() % math.max(anim.intensity, 0.01)) * anim.speed), 0, 1))
		end
	end)
	Library.SetFlags[flagMode] = setMode
	Library.SetFlags[flagSpeed] = setSpeed
	Library.SetFlags[flagInt] = setIntensity
	cp.SetAnimation = function(_, mode) setMode(mode) end

	Library.OnUnload = Library.OnUnload or {}
	table.insert(Library.OnUnload, function() pcall(function() P.Root:Destroy() end) end)
	local default = field(Data, "Default", "default") or Color3.new(1, 1, 1)
	set(default, field(Data, "Alpha", "alpha"))
	-- SetFlags keeps the current alpha (a config stores the colour as hex)
	Library.SetFlags[flag] = function(v) set(v, cp.Alpha) end
	return cp
end

-- ---- Keybind ----
function Library.AddKeybind(owner, row, Data, ownerToggle)
	Data = Data or {}
	local flag = field(Data, "Flag", "flag") or Library:NextFlag()
	local name = field(Data, "Name", "name") or "Keybind"
	local callback = field(Data, "Callback", "callback")
	local passive = field(Data, "Passive", "passive") and true or false
	local K = Build.KeyPill(row)
	K.Root.LayoutOrder = 1
	local kb = { Toggled = false, Key = nil, Mode = "Toggle", Flag = flag, Picking = false, Items = {} }
	kb.Items.Pill = Library.Wrap(K.Root)
	local keyItem = Library.KeyList and Library.KeyList:Add("None", "None", "None")
	if keyItem and keyItem.Instance then keyItem.Instance.Visible = false end

	local function writeFlags()
		local f = Library.Flags[flag]
		if type(f) ~= "table" then f = {} Library.Flags[flag] = f end
		f.Mode, f.Key, f.Toggled = kb.Mode, kb.Key, kb.Toggled
	end
	local function update()
		if ownerToggle then kb.Toggled = ownerToggle.Value == true end   -- a toggle's keybind shows the toggle's real state
		writeFlags()
		K.text.Text = keyText(kb.Key)
		K.Root.Size = UDim2.new(0, math.max(20, #K.text.Text * 6 + 10), 0, 13)
		Library:ChangeItemTheme(K.text, { TextColor3 = kb.Toggled and "Accent" or "Dim Text" })
		Library.fx.tween(K.text, { TextColor3 = kb.Toggled and Library.Theme.Accent or Library.Theme["Dim Text"] }, 0.2)
		if keyItem then keyItem:Set(kb.Mode, name, keyText(kb.Key)) keyItem:SetStatus(kb.Toggled) end
	end
	local function fire() if callback then Library:SafeCall(callback, kb.Toggled) end end

	function kb:Get() return kb.Toggled, kb.Key, kb.Mode end
	function kb:SetVisibility(v) K.Root.Visible = v end
	function kb:SetMode(mode)
		kb.Mode = mode
		if ownerToggle then
			if mode == "Always" and not passive and not ownerToggle.Value then ownerToggle:Set(true) end
			kb.Toggled = ownerToggle.Value == true
		else kb.Toggled = mode == "Always" end
		update() fire()
	end
	function kb:Press(down)
		if ownerToggle and not passive then
			if kb.Mode == "Toggle" then ownerToggle:Set(not ownerToggle.Value)
			elseif kb.Mode == "Hold" then ownerToggle:Set(down == true)
			elseif kb.Mode == "Always" then ownerToggle:Set(true) end
			kb.Toggled = ownerToggle.Value == true
		elseif ownerToggle then kb.Toggled = ownerToggle.Value == true
		elseif kb.Mode == "Toggle" then kb.Toggled = not kb.Toggled
		elseif kb.Mode == "Hold" then kb.Toggled = down == true
		else kb.Toggled = true end
		update() fire()
	end
	function kb:Set(v)
		if typeof(v) == "EnumItem" then
			kb.Key = (v == Enum.KeyCode.Escape or v == Enum.KeyCode.Backspace) and "None" or tostring(v)
			update() fire()
		elseif type(v) == "string" and table.find({ "Toggle", "Hold", "Always" }, v) then
			kb:SetMode(v)
		elseif type(v) == "table" then
			local k = v.Key
			if typeof(k) == "EnumItem" then k = tostring(k) end
			kb.Key = (k == nil or k == "Backspace" or k == "[-]") and "None" or tostring(k)
			kb:SetMode(table.find({ "Toggle", "Hold", "Always" }, v.Mode) and v.Mode or "Toggle")   -- like the old lib: Always switches the toggle on
		end
		kb.Picking = false
	end

	-- right click: mode popup
	local winRoot = Library.popupRoot(owner.Section)
	local P = Build.Panel(winRoot)
	P.Root.Visible, P.Root.ZIndex = false, 1000
	P.Root.Size = UDim2.new(0, 70, 0, 58)
	Library.fx.shadow(P.Root, { radius = 10, transparency = 0.15 })
	Library.fx.bevel(P.Root, 0.08)
	Library.fx.shadow(K.Root, { radius = 5, transparency = 0.5 })
	Library.listLayout(P.rows, 0)
	for _, mode in { "Toggle", "Hold", "Always" } do
		local O = Build.Option(P.rows)
		O.Root.Size, O.Root.BackgroundTransparency = UDim2.new(1, 0, 0, 18), 1
		O.text.Text = mode
		O.text.Size = UDim2.new(1, -12, 0, 14)
		click(O.Root, function() kb:SetMode(mode) P.Root.Visible = false end)
	end
	local rb = click(K.Root)
	Library:Connect(rb.MouseButton2Click, function()
		P.Root.Visible = not P.Root.Visible
		Library.popupAt(P.Root, winRoot, K.Root, 4)
	end)
	Library:Connect(rb.MouseButton1Click, function()
		if kb.Picking then return end
		kb.Picking = true
		K.text.Text = "..."
		Library.fx.tween(K.text, { TextColor3 = Library.Theme.Accent }, 0.15)
		local c
		c = UserInputService.InputBegan:Connect(function(i)
			if i.UserInputType == Enum.UserInputType.Keyboard then kb:Set(i.KeyCode) else kb:Set(i.UserInputType) end
			c:Disconnect()
		end)
	end)
	Library:Connect(UserInputService.InputBegan, function(i)
		if P.Root.Visible and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) and not Library:IsMouseOverFrame(P.Root) and not Library:IsMouseOverFrame(K.Root) then P.Root.Visible = false end
		if kb.Picking or UserInputService:GetFocusedTextBox() then return end
		if kb.Key and (tostring(i.KeyCode) == kb.Key or tostring(i.UserInputType) == kb.Key) then
			if kb.Mode == "Toggle" then kb:Press() elseif kb.Mode == "Hold" then kb:Press(true) end
		end
	end)
	Library:Connect(UserInputService.InputEnded, function(i)
		if kb.Key and (tostring(i.KeyCode) == kb.Key or tostring(i.UserInputType) == kb.Key) and kb.Mode == "Hold" then kb:Press(false) end
	end)
	if ownerToggle then
		table.insert(ownerToggle.Listeners, function() update() end)
	end

	Library.OnUnload = Library.OnUnload or {}
	table.insert(Library.OnUnload, function() pcall(function() P.Root:Destroy() end) end)
	local default = field(Data, "Default", "default")
	local mode = field(Data, "Mode", "mode") or "Toggle"
	if default then kb:Set({ Key = default, Mode = mode }) else kb.Mode = mode update() end
	Library.SetFlags[flag] = function(v) kb:Set(v) end
	return kb
end


